SELECT CAST(id AS TEXT) AS id, CAST(subject AS TEXT) AS subject, CAST(kind AS TEXT) AS kind, CAST(state AS TEXT) AS state, CAST(send_id AS TEXT) AS send_id, CAST(connection_id AS TEXT) AS connection_id, CAST(session_id AS TEXT) AS session_id, CAST(sent_version AS TEXT) AS sent_version, CAST(next_attempt_at AS TEXT) AS next_attempt_at, CAST(attempts AS TEXT) AS attempts, CAST(first_failed_at AS TEXT) AS first_failed_at, CAST(last_error_class AS TEXT) AS last_error_class, CAST(last_error AS TEXT) AS last_error, CAST(created_at AS TEXT) AS created_at, CAST(updated_at AS TEXT) AS updated_at FROM central_work_attempts ORDER BY id;
